    p=argparse.ArgumentParser();p.add_argument('folder',type=Path);a=p.parse_args();r=check(a.folder.resolve());print(json.dumps(r,ensure_ascii=False,indent=2));raise SystemExit(0 if r['mechanical_pass'] else 1)
